import sqlite3
import numpy as np
from pymilvus import connections, Collection
import json

# Step 0: Connect to databases
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db"
}

milvus_config = {
    'collections': {
        'reviews': 'reviews'
    },
    'host': 'localhost',
    'port': '19530'
}

# Connect to Milvus
connections.connect(host=milvus_config['host'], port=milvus_config['port'])
review_collection = Collection(milvus_config['collections']['reviews'])
review_collection.load()

# Helper: get embedding for query (assuming pre-defined encoder)
# In practice, you'd use the same model used to generate review embeddings
from sentence_transformers import SentenceTransformer
encoder = SentenceTransformer('all-MiniLM-L6-v2')

def get_sqlite_connection(db_name):
    return sqlite3.connect(sqlite_paths[db_name])

try:
    # Step 1: Find massage businesses in Tampa
    conn_biz = get_sqlite_connection('business')
    cursor = conn_biz.cursor()
    cursor.execute("""
        SELECT business_id, name, address, categories 
        FROM business 
        WHERE city = ? AND categories LIKE ?
    """, ('Tampa', '%Massage%'))
    tampa_massage_businesses = cursor.fetchall()
    conn_biz.close()

    if not tampa_massage_businesses:
        print('No massage businesses found in Tampa.')
        exit()

    business_ids = [row[0] for row in tampa_massage_businesses]
    business_dict = {row[0]: {'name': row[1], 'address': row[2]} for row in tampa_massage_businesses}

    # Step 2: Vector search in Milvus for pain relief relevance
    query_text = "specializes in pain relief or back pain treatment"
    query_embedding = encoder.encode(query_text).tolist()

    # Build expr for filtering by business_id
    id_expr = " || ".join([f'business_id == \"{bid}\"' for bid in business_ids])
    if len(business_ids) > 1:
        id_expr = f"({id_expr})"
    elif len(business_ids) == 1:
        id_expr = f"business_id == \"{business_ids[0]}\""
    else:
        id_expr = ""

    search_params = {
        "metric_type": "L2",
        "params": {"nprobe": 10}
    }

    results = review_collection.search(
        data=[query_embedding],
        anns_field="embedding",
        param=search_params,
        limit=10,
        expr=id_expr if id_expr else None,
        output_fields=["business_id", "review_id"]
    )

    # Extract matched business_ids and scores
    scored_businesses = {}
    for hit in results[0]:
        bid = hit.entity.get('business_id')
        score = hit.distance  # lower = more similar for L2
        if bid not in scored_businesses or score < scored_businesses[bid]['score']:
            scored_businesses[bid] = {'score': score}

    # Step 3: Rank and output
    ranked = []
    for bid in scored_businesses:
        if bid in business_dict:
            ranked.append({
                'name': business_dict[bid]['name'],
                'address': business_dict[bid]['address'],
                'relevance_score': scored_businesses[bid]['score']
            })

    # Sort by relevance (lower L2 distance = higher relevance)
    ranked.sort(key=lambda x: x['relevance_score'])

    print("Top massage therapists in Tampa specializing in pain relief:")
    for i, therapist in enumerate(ranked[:5]):
        print(f"{i+1}. {therapist['name']} - {therapist['address']} (Relevance: {therapist['relevance_score']:.2f})")

except Exception as e:
    print(f"Error: {e}")
finally:
    connections.disconnect('default')
